set -e

with_local() {
  local out=$(false)
  echo "with_local: still running, out is [$out]"
}

declared_first() {
  local out
  out=$(false)
  echo "declared_first: never printed"
}

with_local
declared_first
echo "never printed either"

#!/usr/bin/env bash
set -euo pipefail
SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"

die() {
  printf 'error: %s\n' "$*" >&2
  exit 1
}

main() {
  local hosts="$SCRIPT_DIR/hosts.txt"
  [[ -f $hosts ]] || die "no host list at $hosts"

  echo "Checking $(wc -l < "$hosts") hosts from $hosts"
  while IFS= read -r host; do
    echo "- $host: ok"
  done < "$hosts"
}

main "$@"

#!/usr/bin/env bash
set -euo pipefail
SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"

die() {
  printf 'error: %s\n' "$*" >&2
  exit 1
}

main() {
  local month input
  for month in 08 09 10; do
    input="$SCRIPT_DIR/reports/sales-2026-$month.csv"
    [[ -f $input ]] || die "no such file: reports/sales-2026-$month.csv"
    printf '2026-%s revenue: %s\n' "$month" "$(awk -F, 'NR > 1 {sum += $3} END {print sum}' "$input")"
  done
}

main "$@"

