#!/usr/bin/env bash
set -euo pipefail
SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"

die() {
  printf 'error: %s\n' "$*" >&2
  exit 1
}

main() {
  local data="$SCRIPT_DIR/data.csv"
  [[ -f $data ]] || die "data.csv not found"

  echo "Totals from data.csv"
  tail -n +2 "$data" | awk -F, '{total[$3] += $4} END {for (s in total) print s, total[s]}' | sort
}

main "$@"
